(function(){'use strict';var sheet=document.getElementById('sheet');if(!sheet)return;function strip(root){root.querySelectorAll('.direct-bounds-overlay-fixed,.welog-layout-overlay-fixed,.welog-layout-hud,.st-toolbar,.st-resize,.st-rotate,.direct-crop-ui,.guide-line').forEach(function(n){n.remove()});root.querySelectorAll('.direct-sticker').forEach(function(n){n.style.outline='none'})}function modal(){var m=document.querySelector('.welog-exact-shot');if(!m){m=document.createElement('div');m.className='welog-exact-shot';m.hidden=true;m.innerHTML='<section class="welog-exact-shot-dialog"><header class="welog-exact-shot-head"><div><small>PREVIEW</small><b>저장 미리보기</b></div><button type="button" aria-label="닫기">×</button></header><div class="welog-exact-shot-body"><div class="welog-preview-viewport"><div class="welog-preview-fit"></div></div></div></section>';document.body.appendChild(m);m.addEventListener('click',function(e){if(e.target===m||e.target.closest('.welog-exact-shot-head button'))m.hidden=true})}return m}function preview(){var m=modal(),viewport=m.querySelector('.welog-preview-viewport'),fit=m.querySelector('.welog-preview-fit'),body=m.querySelector('.welog-exact-shot-body');fit.innerHTML='';var clone=sheet.cloneNode(true);clone.removeAttribute('id');clone.classList.add('welog-preview-live-clone');strip(clone);clone.style.zoom='1';clone.style.transform='none';fit.appendChild(clone);m.hidden=false;requestAnimationFrame(function(){requestAnimationFrame(function(){var r=sheet.getBoundingClientRect(),w=Math.max(1,Math.round(r.width)),h=Math.max(1,Math.round(r.height));var cs=getComputedStyle(sheet),z=parseFloat(cs.zoom)||1;if(z!==1){w=Math.max(1,Math.round(sheet.offsetWidth));h=Math.max(1,Math.round(sheet.offsetHeight))}var bw=Math.max(1,body.clientWidth-32),bh=Math.max(1,body.clientHeight-32),s=Math.min(1,bw/w,bh/h);viewport.style.width=(w*s)+'px';viewport.style.height=(h*s)+'px';fit.style.width=w+'px';fit.style.height=h+'px';fit.style.transformOrigin='top left';fit.style.transform='scale('+s+')';clone.style.width=w+'px';clone.style.height=h+'px';clone.style.position='relative';clone.style.left='0';clone.style.top='0'})})}function replace(){var old=document.getElementById('previewBtn');if(!old)return;var b=old.cloneNode(true);old.replaceWith(b);b.id='previewBtn';b.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();preview()},true)}replace()})();